import React, { useState, useEffect } from 'react';

// --- SVG Icons (Self-contained components) ---
const CheckCircleIcon = ({ className }) => (
  <svg className={className} xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor">
    <path strokeLinecap="round" strokeLinejoin="round" d="M9 12.75L11.25 15 15 9.75M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
  </svg>
);

const ArrowPathIcon = ({ className }) => (
  <svg className={`${className} animate-spin`} xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor">
    <path strokeLinecap="round" strokeLinejoin="round" d="M16.023 9.348h4.992v-.001M2.985 19.644v-4.992m0 0h4.992m-4.993 0l3.181 3.183a8.25 8.25 0 0011.664 0l3.18-3.185m-3.18 3.182V6.108a8.25 8.25 0 00-11.664 0v3.185" />
  </svg>
);

const ChartBarIcon = ({ className }) => (
  <svg className={className} xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor">
    <path strokeLinecap="round" strokeLinejoin="round" d="M3 13.125C3 12.504 3.504 12 4.125 12h2.25c.621 0 1.125.504 1.125 1.125v6.75C7.5 20.496 6.996 21 6.375 21h-2.25A1.125 1.125 0 013 19.875v-6.75zM9.75 8.625c0-.621.504-1.125 1.125-1.125h2.25c.621 0 1.125.504 1.125 1.125v11.25c0 .621-.504 1.125-1.125 1.125h-2.25a1.125 1.125 0 01-1.125-1.125V8.625zM16.5 4.125c0-.621.504-1.125 1.125-1.125h2.25C20.496 3 21 3.504 21 4.125v15.75c0 .621-.504 1.125-1.125 1.125h-2.25a1.125 1.125 0 01-1.125-1.125V4.125z" />
  </svg>
);

// --- Main Application Component ---
function FlowCastPrototype() {
  const [currentView, setCurrentView] = useState('integration'); // 'integration' or 'forecast'
  const [integrations, setIntegrations] = useState({
    xero: { status: 'disconnected', name: 'Xero' },
    myob: { status: 'disconnected', name: 'MYOB' },
    quickbooks: { status: 'disconnected', name: 'QuickBooks' },
  });
  const [connectingService, setConnectingService] = useState(null);
  const [isForecastLoading, setIsForecastLoading] = useState(false);

  const isAnyIntegrationConnected = Object.values(integrations).some(i => i.status === 'connected');

  const handleConnect = (service) => {
    setConnectingService(service);
    setTimeout(() => {
      setIntegrations(prev => ({ ...prev, [service]: { ...prev[service], status: 'connected' } }));
      setConnectingService(null);
    }, 2000);
  };

  const handleViewForecast = () => {
    setIsForecastLoading(true);
    setTimeout(() => {
      setCurrentView('forecast');
      setIsForecastLoading(false);
    }, 2500);
  };

  const Header = () => (
    <header className="bg-white shadow-sm">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-4 flex justify-between items-center">
        <div className="flex items-center gap-2">
          <ChartBarIcon className="h-8 w-8 text-blue-600" />
          <h1 className="text-2xl font-bold text-slate-800">FlowCast AI</h1>
        </div>
        <div className="flex items-center gap-4">
          <span className="text-sm text-slate-600 hidden sm:block">Amelia Chen</span>
          <img
            className="h-10 w-10 rounded-full object-cover"
            src="https://i.pravatar.cc/150?u=amelia.chen"
            alt="Amelia Chen"
          />
        </div>
      </div>
    </header>
  );

  const IntegrationView = () => (
    <div className="max-w-4xl mx-auto">
      <div className="text-center mb-10">
        <h2 className="text-3xl font-bold tracking-tight text-slate-900 sm:text-4xl">Welcome, Amelia</h2>
        <p className="mt-4 text-lg text-slate-600">Connect your financial accounts to generate your cash flow forecast.</p>
      </div>
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {Object.entries(integrations).map(([key, value]) => (
          <div key={key} className={`bg-white rounded-lg shadow-md p-6 flex flex-col items-center justify-between transition-all duration-300 ${value.status === 'connected' ? 'border-2 border-emerald-500' : 'border border-slate-200'}`}>
            <img src={`https://logo.clearbit.com/${key}.com`} alt={`${value.name} logo`} className="h-12 mb-4 grayscale opacity-80" />
            <h3 className="text-xl font-semibold text-slate-800 mb-2">{value.name}</h3>
            <p className="text-sm text-slate-500 text-center mb-6">Sync your invoices, bills, and payroll data.</p>
            <button
              onClick={() => handleConnect(key)}
              disabled={value.status !== 'disconnected' || connectingService !== null}
              className={`w-full px-4 py-2 rounded-md font-semibold text-white transition-all duration-200 flex items-center justify-center disabled:opacity-50 disabled:cursor-not-allowed ${{
                'disconnected': 'bg-blue-600 hover:bg-blue-700',
                'connecting': 'bg-blue-400',
                'connected': 'bg-emerald-500',
              }[connectingService === key ? 'connecting' : value.status]}`}>
              {connectingService === key ? (
                <><ArrowPathIcon className="h-5 w-5 mr-2" /> Connecting...</>
              ) : value.status === 'connected' ? (
                <><CheckCircleIcon className="h-5 w-5 mr-2" /> Connected</>
              ) : (
                'Connect'
              )}
            </button>
          </div>
        ))}
      </div>
      <div className="mt-12 text-center">
        <button
          onClick={handleViewForecast}
          disabled={!isAnyIntegrationConnected || isForecastLoading}
          className="bg-slate-800 text-white font-bold py-3 px-8 rounded-lg shadow-lg hover:bg-slate-900 disabled:bg-slate-400 disabled:cursor-not-allowed transition-transform duration-200 hover:scale-105 disabled:scale-100 flex items-center justify-center mx-auto"
        >
          {isForecastLoading ? (
            <><ArrowPathIcon className="h-5 w-5 mr-3" /> Generating Forecast...</>
          ) : (
            'View Cash Flow Forecast'
          )}
        </button>
      </div>
    </div>
  );

  const ForecastView = () => {
    const forecastData = [60, 65, 75, 70, 85, 95, 90, 105, 120, 110, 125, 130];
    const maxVal = Math.max(...forecastData);

    return (
      <div className="max-w-7xl mx-auto">
        <div className="flex justify-between items-center mb-8">
            <h2 className="text-3xl font-bold tracking-tight text-slate-900">90-Day Cash Flow Forecast</h2>
            <button onClick={() => setCurrentView('integration')} className="text-sm text-blue-600 hover:underline">← Back to Integrations</button>
        </div>
        {/* KPI Cards */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
            <div className="bg-white p-6 rounded-lg shadow-md border-l-4 border-blue-500">
                <h3 className="text-slate-500 text-sm font-medium">Opening Balance</h3>
                <p className="text-3xl font-bold text-slate-800 mt-1">$147,830</p>
            </div>
            <div className="bg-white p-6 rounded-lg shadow-md border-l-4 border-emerald-500">
                <h3 className="text-slate-500 text-sm font-medium">Projected Net Flow</h3>
                <p className="text-3xl font-bold text-emerald-600 mt-1">+$82,170</p>
            </div>
            <div className="bg-white p-6 rounded-lg shadow-md border-l-4 border-slate-600">
                <h3 className="text-slate-500 text-sm font-medium">Projected Closing Balance</h3>
                <p className="text-3xl font-bold text-slate-800 mt-1">$230,000</p>
            </div>
        </div>
        {/* Chart and Transactions */}
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
            <div className="lg:col-span-2 bg-white p-6 rounded-lg shadow-md">
                <h3 className="font-semibold text-slate-800 mb-4">Cash Balance Over Time (in thousands AUD)</h3>
                <div className="h-80 w-full bg-slate-50 rounded-md p-4">
                  <svg width="100%" height="100%" viewBox="0 0 500 200" preserveAspectRatio="none">
                    <path d="M 0 180 L 500 180" stroke="#e2e8f0" strokeWidth="1" />
                    <path d="M 0 120 L 500 120" stroke="#e2e8f0" strokeWidth="1" />
                    <path d="M 0 60 L 500 60" stroke="#e2e8f0" strokeWidth="1" />
                    <path d="M 0 0 L 500 0" stroke="#e2e8f0" strokeWidth="1" />
                    <polyline
                        fill="none"
                        stroke="#3b82f6"
                        strokeWidth="2"
                        points={
                            forecastData.map((p, i) => {
                                const x = (i / (forecastData.length - 1)) * 500;
                                const y = 200 - (p / (maxVal * 1.1)) * 200;
                                return `${x},${y}`;
                            }).join(' ')
                        }
                    />
                  </svg>
                </div>
            </div>
            <div className="bg-white p-6 rounded-lg shadow-md">
                <h3 className="font-semibold text-slate-800 mb-4">Early Warning Alerts</h3>
                <ul className="space-y-4">
                    <li className="flex items-start gap-3">
                        <div className="w-10 h-10 bg-amber-100 text-amber-600 rounded-lg flex items-center justify-center flex-shrink-0 mt-1">⚠️</div>
                        <div>
                            <p className="font-semibold text-slate-700">Potential Shortfall</p>
                            <p className="text-sm text-slate-500">July 15: Projected balance close to credit limit.</p>
                        </div>
                    </li>
                    <li className="flex items-start gap-3">
                        <div className="w-10 h-10 bg-red-100 text-red-600 rounded-lg flex items-center justify-center flex-shrink-0 mt-1">❗</div>
                        <div>
                            <p className="font-semibold text-slate-700">Large Invoice Overdue</p>
                            <p className="text-sm text-slate-500">Invoice #INV-0451 ($15,200) is 7 days overdue.</p>
                        </div>
                    </li>
                </ul>
            </div>
        </div>
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-slate-50 font-sans">
      <Header />
      <main className="py-10 px-4 sm:px-6 lg:px-8">
        {currentView === 'integration' ? <IntegrationView /> : <ForecastView />}
      </main>
    </div>
  );
}

export default FlowCastPrototype;

